// Certificate authorities for programs that verify HTTPS with the system
// store (cloudflared, curl, git, Python). A minimal Linux environment on a
// phone often has no ca-certificates package and no way to install it, so
// those programs reject every HTTPS connection. Node.js carries its own
// copy of the same root certificates, and that copy is written out here.
const fs = require("fs");
const tls = require("tls");
const path = require("path");

const SYSTEM_BUNDLES = [
  "/etc/ssl/certs/ca-certificates.crt",
  "/etc/pki/tls/certs/ca-bundle.crt",
  "/etc/ssl/cert.pem",
  "/etc/ssl/ca-bundle.pem",
];

const hasContent = (file) => {
  try {
    return fs.statSync(file).size > 1024;
  } catch {
    return false;
  }
};

const systemBundle = (candidates = SYSTEM_BUNDLES) => candidates.find(hasContent) || null;

// Returns the path of a bundle this agent wrote, or null when the system
// already has one and nothing needs to change.
const ensureCaBundle = (home, candidates) => {
  if (systemBundle(candidates)) return null;

  const file = path.join(home, "ca-bundle.crt");
  const content = `${tls.rootCertificates.join("\n")}\n`;

  let current = null;
  try {
    current = fs.readFileSync(file, "utf8");
  } catch {
    // Not written yet.
  }

  if (current !== content) {
    fs.writeFileSync(`${file}.tmp`, content, { mode: 0o644 });
    fs.renameSync(`${file}.tmp`, file);
  }

  return file;
};

// Point child processes at the bundle. Values already set are kept.
const applyCaEnvironment = (home, env = process.env, candidates) => {
  const file = ensureCaBundle(home, candidates);
  if (!file) return null;

  for (const name of ["SSL_CERT_FILE", "CURL_CA_BUNDLE", "GIT_SSL_CAINFO"]) {
    if (!env[name]) env[name] = file;
  }

  return file;
};

module.exports = { ensureCaBundle, applyCaEnvironment, systemBundle };

